/* Misión Ambiental: experiencia de aula, sin cuentas ni datos personales. */
(() => {
'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const P = window.PROGRAM_DATA;
const cases = window.CASES;
const KEY = 'colmayor-mision-ambiental-v1';
let stored = {};
try { stored = JSON.parse(localStorage.getItem(KEY) || '{}'); } catch (_) {}
let settings = { teams:['Equipo Ceiba','Equipo Río','Equipo Cóndor'], seconds:45, ...stored.settings };
let history = stored.history || {};
let game = null;
let route = '';
let timer = null;
let seconds = settings.seconds;
let running = false;
let narrate = false;
let soundContext = null;
const letters = ['A','B','C'];
const titles = ['Explora','Mide','Transforma'];
function save(){try{localStorage.setItem(KEY,JSON.stringify({settings,history}));}catch(_){toast('Tu navegador no permite guardar. La sesión sigue activa.');}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function speak(text){if(!narrate || !('speechSynthesis' in window))return; speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='es-CO';u.rate=.97;speechSynthesis.speak(u);}
function chime(){if(!narrate)return;try{soundContext ||= new (window.AudioContext||window.webkitAudioContext)();const o=soundContext.createOscillator(),v=soundContext.createGain();o.connect(v);v.connect(soundContext.destination);o.frequency.setValueAtTime(660,soundContext.currentTime);o.frequency.exponentialRampToValueAtTime(880,soundContext.currentTime+.15);v.gain.setValueAtTime(.035,soundContext.currentTime);v.gain.exponentialRampToValueAtTime(.001,soundContext.currentTime+.4);o.start();o.stop(soundContext.currentTime+.4);}catch(_){}}
function stopTimer(){clearInterval(timer);timer=null;running=false;}
function setTime(){seconds=settings.seconds;stopTimer();paintTime();}
function paintTime(){const el=$('#time');if(el)el.textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;const b=$('#timer-toggle');if(b){b.textContent=running?'Ⅱ':'▶';b.setAttribute('aria-label',running?'Pausar temporizador':'Iniciar temporizador');}$('#timer')?.classList.toggle('expired',seconds===0);}
function toggleTimer(){if(running){stopTimer();paintTime();return;}if(seconds===0)seconds=settings.seconds;running=true;paintTime();timer=setInterval(()=>{seconds=Math.max(0,seconds-1);if(!seconds){stopTimer();toast('Tiempo para conversar. Puedes continuar sin penalización.');chime();}paintTime();},1000);}
function navigate(){stopTimer();if('speechSynthesis' in window)speechSynthesis.cancel();const path=decodeURIComponent(location.hash.slice(1)||'inicio');route=path;document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===path||(a.dataset.nav==='inicio'&&path.startsWith('mision/'))));document.body.classList.remove('fullscreen-mode');if(path.startsWith('mision/')){const id=path.split('/')[1];const c=cases.find(x=>x.id===id);if(!c){location.hash='inicio';return;}if(!game||game.id!==id)startGame(id);else if(game.completed)renderResults();else renderGame();}else if(path==='programa')renderProgram();else if(path==='aula')renderTeacher();else if(path==='herramientas')renderTools();else renderHome();window.scrollTo(0,0);}
function scene(id,{stage=-1,selected=-1,revealed=false,mini=false,sim=60,rain=true,corridor=0,controls=[]}={}){
const trees=(coords,color='#346d4d')=>coords.map(([x,y,s=1])=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M0 5v23" stroke="#577458" stroke-width="3"/><path d="M-17 12 0-18 17 12Z" fill="${color}"/><path d="M-14 0 0-25 14 0Z" fill="#51865a"/></g>`).join('');
let shape='';
if(id==='agua')shape=`<rect width="600" height="330" fill="#dce8d1"/><path d="M0 85 120 26 238 88 359 18 600 96V0H0" fill="#bdcfac"/><path d="M-30 260C92 116 150 257 265 179S425 134 644 47" fill="none" stroke="#acc8a0" stroke-width="115"/><path d="M-30 260C92 116 150 257 265 179S425 134 644 47" fill="none" stroke="#82bec0" stroke-width="73"/><path d="M238 191C330 142 430 130 644 47" fill="none" stroke="${stage===2?'#78b6ad':'#99ac91'}" stroke-width="52" opacity="${stage===2?.85-sim/150:.7}"/><path d="M-30 251C90 120 150 245 271 173S425 124 644 38" fill="none" stroke="#e2f1dd" stroke-width="3" stroke-dasharray="30 18" opacity=".65"><animate attributeName="stroke-dashoffset" from="0" to="-96" dur="8s" repeatCount="indefinite"/></path><path d="M297 111V157L276 173" fill="none" stroke="#a3a696" stroke-width="14"/><path d="M297 111V157L276 173" fill="none" stroke="#d8dccb" stroke-width="6"/><g transform="translate(246 46)"><path d="M0 70 0 12 35 34 35 12 73 34 73 12 112 37V70Z" fill="#f5f0db" stroke="#7a967c"/><path d="M89 33V-5h18v38" fill="#bc9f81"/><path d="M98-5c-20-25 21-23 1-44" fill="none" stroke="#ffffffa8" stroke-width="12"/><path d="M10 48h17m18 0h17m18 0h17" stroke="#829b8c" stroke-width="10"/><path d="M0 70h112v9H0" fill="#7b9980"/></g>${trees([[55,85,1.1],[102,65,.8],[168,82,.7],[447,244,1],[489,275,1.1],[535,235,.8],[62,295,.9],[580,166,.8]])}<g fill="#f4faeb" opacity=".9"><path d="m144 203 16-5-4 9m218-81 16-5-4 9m112-21 16-5-4 9"/></g><text x="22" y="31" fill="#57715a" font-size="10" letter-spacing="2">CUENCA · ESCENA SIMULADA</text>`;
else if(id==='bosque')shape=`<rect width="600" height="330" fill="#dfd5a8"/><path d="M0 0H600V70L250 60 0 100" fill="#c2d4aa"/><path d="M-20 280 170 210 365 222 620 85" fill="none" stroke="#b6a78a" stroke-width="45"/><path d="M-20 280 170 210 365 222 620 85" fill="none" stroke="#f3eee1" stroke-width="34"/><path d="M-20 280 170 210 365 222 620 85" fill="none" stroke="#c5bda6" stroke-width="2" stroke-dasharray="12 10"/><path d="M0 0 176 0 225 69 169 166 43 194 0 154Z" fill="#86a76b"/><path d="M324 0H600V96L517 160 428 124 360 87Z" fill="#98b178"/><path d="M277 246 373 253 422 330H238Z" fill="#91ab70"/><path d="M155 60Q260 25 400 53" stroke="#85a76b" stroke-width="18" fill="none"/>${corridor===1?'<path d="M100 125Q178 185 322 286" fill="none" stroke="#6e9651" stroke-width="30"/><path d="M100 125Q178 185 322 286" fill="none" stroke="#c9ee75" stroke-width="4" stroke-dasharray="5 5"/>':''}${corridor===2?'<path d="M322 290Q355 150 475 86" fill="none" stroke="#7d9b56" stroke-width="39"/><path d="M322 290Q355 150 475 86" fill="none" stroke="#f5d67b" stroke-width="4" stroke-dasharray="5 5"/>':''}${trees([[25,55],[68,25,.8],[110,60],[153,99,1],[82,123,.9],[26,132,.8],[165,28,.7],[394,37,.9],[435,72],[483,27],[520,75,1.1],[567,35,.9],[290,286,.75],[340,303,.8],[370,285,.7]])}<g fill="#173b32"><path d="m107 97 9-7 13 2 3 9-10 6-12-3m-6-5-6 8m31-7 10-6"/><path d="m445 101 9-7 13 2 3 9-10 6-12-3m-6-5-6 8m31-7 10-6"/></g><text x="20" y="321" fill="#6c7253" font-size="10" letter-spacing="2">PAISAJE · ESCENA SIMULADA</text>`;
else if(id==='obra')shape=`<rect width="600" height="330" fill="${rain?'#d6dfd2':'#e9ecd8'}"/><path d="M0 133 124 28 267 125 410 32 600 146V330H0" fill="#b6ca9d"/><path d="m75 330 110-170 175-45 125-80 36 23-125 104-185 45L123 330" fill="#c8b796"/><path d="m82 330 113-158 176-39L502 40" stroke="#f5eee0" stroke-width="33" fill="none"/><path d="M-20 279Q170 194 282 262T625 217" stroke="#89bbb4" stroke-width="58" fill="none"/>${rain?'<path d="M233 182 277 257" stroke="#b49971" stroke-width="27" opacity=".8"/><path d="M278 264Q420 295 625 215" stroke="#b39f7a" stroke-width="37" fill="none"/>':''}<path d="m200 143 72 12 26 52-74-15Z" fill="#b99c77"/>${controls.includes(0)?'<path d="m197 145 77 15 24 43-74-15Z" fill="#71904a"/><path d="m206 154 67 16m-61-3 69 15" stroke="#a4bf73" stroke-width="4"/>':''}${controls.includes(1)?'<path d="m225 198 44 18 20 37" fill="none" stroke="#607b70" stroke-width="9"/>':''}${controls.includes(2)?'<path d="m270 231 45 8-8 31-44-8Z" fill="#d3d8bb" stroke="#5c7b64" stroke-width="3"/><path d="m270 240 34 5-3 15-32-5Z" fill="#94aaa0"/>':''}<g transform="translate(326 117)"><path d="M0 0h48v14H0" fill="#edb54e"/><path d="M35 0v-19h15V1M8 0V-15h19V0" fill="#e3b34d" stroke="#8a8961"/><circle cx="9" cy="16" r="7" fill="#435747"/><circle cx="40" cy="16" r="7" fill="#435747"/></g>${trees([[27,157,.9],[84,117,.8],[400,208,.9],[452,172],[527,154,.7],[562,282,.8]])}${rain?'<g stroke="#698990" stroke-width="1.5" opacity=".55"><path d="m50 5-9 17m62-3-9 17m95-24-9 17m122-24-9 17m93-8-9 17m118-24-9 17m61 1-9 17"/><animateTransform attributeName="transform" type="translate" from="0 0" to="-9 25" dur="1s" repeatCount="indefinite"/></g>':''}<text x="20" y="310" fill="#53705a" font-size="10" letter-spacing="2">OBRA VIAL · ESCENA SIMULADA</text>`;
else shape=`<rect width="600" height="330" fill="#dfdfcf"/><path d="M0 260 300 325 600 215 312 145Z" fill="#c5cdb6"/><path d="m100 139 188-67 201 62-190 73Z" fill="#f5efdc"/><path d="m100 139 199 68v99l-199-72Z" fill="#bac6b3"/><path d="m299 207 190-73v102l-190 70Z" fill="#e2e5d5"/><path d="m100 139 188-67v50l-188 67Z" fill="#f5f2e3"/><path d="m288 72 201 62v51l-201-63Z" fill="#d5dccb"/><path d="m299 156 149-53-101-31-149 53Z" fill="#7c9b86"/><path d="m322 153 145-52M297 144l143-51m-169 43 141-50" stroke="#afc5ab" stroke-width="3"/><path d="m134 180 33 11v41l-33-11m50-22 33 11v41l-33-11m50-22 33 11v41l-33-11" fill="#72988b"/><g transform="translate(65 213)"><ellipse rx="29" ry="12" fill="#7ea3a7"/><path d="M-29 0v55c0 15 58 15 58 0V0" fill="#a7c8c7"/><ellipse rx="29" ry="12" fill="#c7e2dc"/><path d="M0 0v38" stroke="#ffffff80" stroke-width="3"/></g><g transform="translate(530 209)"><path d="M-17-37v40h34v-40" fill="#d0a572"/><path d="M-9-37v-36h18v36" fill="#d0a572"/><path d="M0-73c-17-13 18-18 0-35" stroke="#ffffffe0" stroke-width="10" fill="none"/></g><path d="M36 320V290h24v37M528 300v-32h24v25M562 287v-32h24v25" fill="#85a66a"/>${trees([[27,113,.8],[560,117,.8]])}<text x="20" y="30" fill="#5c7361" font-size="10" letter-spacing="2">PLANTA PILOTO · ESCENA SIMULADA</text>`;
return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 330" role="img" aria-label="${{agua:'Mapa ilustrado de una quebrada con industria y tres puntos de muestreo',bosque:'Mapa de tres parches de bosque separados por una vía y potreros',obra:'Obra vial con talud, drenaje y quebrada',circular:'Planta industrial ilustrada con tanque de agua, proceso y chimenea'}[id]}">${shape}</svg>`;
}
function missionCard(c,i){return `<a class="mission-card" href="#mision/${c.id}" aria-label="Jugar misión ${i+1}: ${esc(c.title)}"><div class="mission-art">${scene(c.id,{mini:true,rain:false})}<span class="case-tag">${esc(c.category)}</span><span class="case-no">0${i+1}</span></div><div class="mission-copy"><div class="mission-meta"><span>◷ ${esc(c.duration)}</span><span>·</span><span>3 niveles</span></div><h3>${esc(c.title)}</h3><p>${esc(c.teaser)}</p><div class="mission-bottom"><span class="${history[c.id]?'complete-label':''}">${history[c.id]?'✓ Misión explorada':'Entrar a la misión'}</span><span class="round-arrow" aria-hidden="true">↗</span></div></div></a>`;}
function renderHome(){
$('#main').innerHTML=`<section class="hero"><div class="hero-content"><div class="eyebrow"><span class="live-dot"></span> TU PRIMER DÍA COMO INGENIERO/A AMBIENTAL</div><h1>El futuro también<br>se <em>diseña.</em></h1><p>Una quebrada, una fábrica, un bosque.<br>Explora el problema. Pon a prueba tus ideas.<br>Descubre lo que puedes transformar.</p><a class="primary" href="#mision/agua">Acepta tu primera misión <span class="button-arrow" aria-hidden="true">↗</span></a><p class="hero-note">4 retos · 4–5 minutos por misión · Un equipo: tu salón</p></div><span class="hero-coordinate"><span class="live-dot"></span> COLOMBIA · TERRITORIO DE POSIBILIDADES</span><div class="hero-location">EL ESCENARIO ES NUESTRO TERRITORIO<b>La próxima decisión es tuya.</b><span>Paisaje ilustrativo generado</span></div></section>
<div class="intro-strip"><div class="intro-label">Esto se aprende jugando.<span>Sin fórmulas de memoria. Con curiosidad.</span></div><div class="intro-step"><span class="step-number">01</span><div><b>Explora la escena</b><small>Encuentra las pistas.</small></div></div><div class="intro-step"><span class="step-number">02</span><div><b>Activa tu kit</b><small>Haz visible lo invisible.</small></div></div><div class="intro-step"><span class="step-number">03</span><div><b>Cambia el resultado</b><small>Decide. Prueba. Transforma.</small></div></div></div>
<section aria-labelledby="missions-title"><div class="section-head"><div><div class="eyebrow">ELIGE DÓNDE DEJAR TU HUELLA</div><h2 id="missions-title">Cuatro misiones. Un mundo por cuidar.</h2></div><p>Casos inspirados en retos de Colombia.<br>Datos simulados. Decisiones que te hacen pensar.</p></div><div class="mission-grid">${cases.map(missionCard).join('')}</div></section>
<section class="invitation"><div><h3>¿Y si esto fuera lo tuyo?</h3><p>Conoce Ingeniería Ambiental del Colegio Mayor de Antioquia.</p></div><a href="#programa" class="text-btn">Descubre tu próxima carrera <span aria-hidden="true">↗</span></a></section>`;
}
function startGame(id){const c=cases.find(x=>x.id===id);game={id,stage:0,selected:null,revealed:false,seen:[],activeClue:null,votes:settings.teams.map(()=>null),records:[],sim:60,rain:false,corridor:0,controls:[],investments:[],prediction:null};setTime();renderGame();}
function current(){return cases.find(x=>x.id===game.id);}
function pointsFor(stage,choice){if(choice===null||choice===undefined)return 0;return current().stages[stage].options[choice]?.score||0;}
function renderChart(chart){if(!chart)return '';return `<div class="data-chart"><div class="chart-title">${esc(chart.title)}</div>${chart.rows.map(r=>`<div class="bar-row "><span>${esc(r.label)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.min(100,r.value/chart.max*100)}%"></div></div><strong>${esc(r.value)} ${esc(chart.unit)}</strong></div>`).join('')}</div>`;}
function labWidget(c){if(game.stage!==2)return '';if(c.id==='agua')return `<div class="lab-control"><label for="treatment">Prueba un tratamiento <span id="treatment-percent">${game.sim}% remoción</span></label><input id="treatment" type="range" min="0" max="95" step="5" value="${game.sim}" aria-label="Porcentaje de remoción de DBO del vertimiento"><div class="outcome-metrics"><div><strong id="dbo-value">${Math.round(420*(1-game.sim/100))} mg/L</strong><small>DBO₅ estimada a la salida</small></div><div><strong id="load-value">${(108.864*(1-game.sim/100)).toFixed(1)} kg/d</strong><small>Carga orgánica estimada</small></div></div><p>Modelo didáctico: entrada 420 mg/L, caudal 3 L/s constante. El cambio de color es ilustrativo; no predice oxígeno en la quebrada.</p></div>`;
if(c.id==='bosque')return `<div class="lab-control"><label>Traza una conexión en el mapa</label><div class="map-actions"><button class="secondary ${game.corridor===1?'active':''}" data-corridor="1">① Conectar bosques</button><button class="secondary ${game.corridor===2?'active':''}" data-corridor="2">② Cruzar la vía</button></div><p id="corridor-note">${game.corridor===1?'La ruta ① conecta el bosque mayor con el parche aislado. Requiere restauración nativa, acuerdos y un cruce seguro de la vía.':game.corridor===2?'La ruta ② cruza la vía: necesita un paso de fauna diseñado y seguimiento, además de restauración.':'Prueba ambas rutas. La ubicación, las especies y la seguridad cambian el diseño.'}</p></div>`;
if(c.id==='obra')return `<div class="lab-control"><label>Coloca defensas antes de la lluvia</label><div class="mitigation-actions">${['Cubrir el talud','Conducir la escorrentía','Retener sedimentos'].map((x,i)=>`<button data-control="${i}" class="chip ${game.controls.includes(i)?'active':''}">${game.controls.includes(i)?'✓':'+'} ${x}</button>`).join('')}</div><p>${game.controls.length}/3 medidas instaladas. ${game.controls.length===3?'Ahora inspecciona y mantén cada medida después de la lluvia.':'Combina controles en la fuente y en la ruta del agua.'}</p></div>`;
return '';}
function fieldPanel(c){return `<section class="field-panel" aria-label="Escena y evidencia"><div class="field-heading"><b>${game.stage===0?'MAPA DE CAMPO':game.stage===1?'ESTACIÓN DE MEDICIÓN':'SIMULADOR DE DECISIONES'}</b><span class="sim-pill">${game.stage===0?`${game.seen.length}/3 pistas`:'Datos simulados'}</span></div><div class="field-scene" id="scene">${scene(c.id,{stage:game.stage,selected:game.selected,revealed:game.revealed,sim:game.sim,rain:game.rain,corridor:game.corridor,controls:game.controls})}${game.stage===0?c.hotspots.map((h,i)=>`<button style="left:calc(${h.x}% - 19px);top:calc(${h.y}% - 19px)" class="hotspot ${game.seen.includes(i)?'seen':''}" data-clue="${i}" aria-label="Inspeccionar ${esc(h.title)}">${game.seen.includes(i)?'✓':i+1}</button>`).join(''):''}${game.stage===1?`<div class="sensor-overlay"><svg viewBox="0 0 40 40" aria-hidden="true"><rect x="7" y="3" width="22" height="31" rx="4"/><path d="M12 9h12v9H12zM12 24h4m4 0h4M29 22h4v14"/></svg><span>${game.revealed?'✓ Campaña de medición completada':'Activa el kit de medición'}</span></div>`:''}</div>${c.id==='obra'?`<div class="weather-toggle"><button data-weather="false" class="chip ${!game.rain?'active':''}">☀ Antes de llover</button><button data-weather="true" class="chip ${game.rain?'active':''}">☂ Después de llover</button></div>`:''}<p class="field-hint">${game.stage===0?'Toca los tres puntos para inspeccionar el escenario.':game.stage===1?'Selecciona un kit y ejecuta la medición para abrir los resultados.':'Interactúa con el escenario y elige un plan de intervención.'}</p><div class="evidence-readout" id="evidence" aria-live="polite">${clueMarkup(c)}</div>${game.stage===1&&game.revealed?renderChart(c.stages[1].chart):''}${labWidget(c)}</section>`;}
function clueMarkup(c){if(game.stage===0){if(game.activeClue!==null){const h=c.hotspots[game.activeClue];return `<div class="eyebrow">PISTA ${game.activeClue+1} ENCONTRADA</div><b class="readout-title">${esc(h.title)}</b><p>${esc(h.text)}</p>`;}return `<div class="eyebrow">BITÁCORA VACÍA</div><b class="readout-title">Todo comienza observando.</b><p>Explora el mapa. Una señal es una pista, no una conclusión.</p>`;}if(game.stage===1&&!game.revealed)return `<div class="eyebrow">EL LABORATORIO ESPERA TU DECISIÓN</div><p>¿Qué necesitas medir para poner a prueba la hipótesis?</p>`;if(game.stage===1&&game.revealed)return `<div class="eyebrow">${c.id==='agua'?'CINCO DÍAS DESPUÉS · LABORATORIO':'RESULTADOS DE LA CAMPAÑA'}</div><p>${esc(c.stages[1].context)} ${c.id==='agua'?'DBO₅: oxígeno que consumen microorganismos en cinco días.':''}</p>`;return `<div class="eyebrow">TU MISIÓN COMO INGENIERO/A</div><p>${esc(c.profession)}</p>`;}
function votePanel(){return `<section class="votes-panel"><h3>La decisión de cada equipo</h3><p>El docente registra las señales A, B o C del salón. ${game.revealed?'Pueden revisar el voto después de conversar.':'Registra antes de revelar para guardar los puntos.'}</p>${settings.teams.map((team,i)=>`<div class="vote-row"><span>${esc(team)}</span><div class="vote-btns" role="group" aria-label="Voto de ${esc(team)}">${letters.map((l,j)=>`<button data-vote="${i}" data-value="${j}" class="${game.votes[i]===j?'chosen':''}" aria-pressed="${game.votes[i]===j}">${l}</button>`).join('')}</div></div>`).join('')}<p class="tiny" style="margin:10px 0 0">${game.revealed?'El voto inicial conserva su puntaje; la revisión sirve para aprender.':'Sin dispositivos individuales. La respuesta central funciona como consenso.'}</p></section>`;}
function feedbackMarkup(c){if(!game.revealed)return '';const opt=c.stages[game.stage].options[game.selected];const high=opt.score===2;return `<div class="feedback ${high?'':'warm'}" role="status"><b>${high?'✓ Decisión sustentada':'↻ Una oportunidad para afinar la idea'}</b><p>${esc(opt.feedback)}</p>${!high?`<p><b>Compara con ${letters[c.stages[game.stage].correct]}:</b> ${esc(c.stages[game.stage].options[c.stages[game.stage].correct].feedback)}</p>`:''}</div>`;}
function readyTask(){if(game.stage!==2)return true;if(game.id==='agua')return game.sim>=80;if(game.id==='bosque')return game.corridor>0;if(game.id==='obra')return game.controls.length===3;return true;}
function taskHint(){if(game.stage!==2||game.id==='circular')return '';const text={agua:'Reto: ajusta el tratamiento para reducir al menos 80% de la carga del vertimiento. Meta didáctica, no límite legal.',bosque:'Reto: prueba una ruta de restauración y revisa las condiciones antes de decidir.',obra:'Reto: instala tres defensas en el mapa para actuar sobre la fuente y el transporte.'}[game.id];return `<p class="task-hint ${readyTask()?'mission-task-complete':''}">${readyTask()?'✓':'↳'} ${text}</p>`;}
function renderGame(){const focused=document.activeElement;const focusKeys=['id','data-clue','data-answer','data-vote','data-corridor','data-control','data-weather','data-invest'];let restore='';if(focused&&focused.closest('#main')){for(const k of focusKeys){if(focused.hasAttribute(k)){restore=k==='id'?'#'+focused.id:'['+k+'="'+focused.getAttribute(k)+'"]';if(k==='data-vote')restore+='[data-value="'+focused.dataset.value+'"]';break;}}}const c=current(),s=c.stages[game.stage],isBudget=c.id==='circular'&&game.stage===2;
$('#main').innerHTML=`<a href="#inicio" class="back">← Todas las misiones</a><div class="game-bar"><div class="game-identity"><div><div class="eyebrow">MISIÓN 0${cases.indexOf(c)+1} · ${esc(c.category)}</div><h1>${esc(c.title)}</h1></div></div><div class="game-tools"><div class="timer" id="timer"><span id="time"></span><button id="timer-toggle" aria-label="Iniciar temporizador">▶</button><button id="timer-reset" aria-label="Reiniciar temporizador">↻</button></div><button class="icon-btn" id="fullscreen" aria-label="Activar vista para proyector" title="Vista para proyector">⛶</button></div></div><div class="progress-steps">${titles.map((t,i)=>`<div aria-current="${i===game.stage?'step':'false'}" class="progress-step ${i===game.stage?'active':i<game.stage?'done':''}"><span>${i<game.stage?'✓':`0${i+1}`}</span>${t}</div>`).join('')}</div>
<div class="game-grid">${isBudget?budgetField():fieldPanel(c)}<section class="question-panel"><div class="eyebrow">NIVEL ${game.stage+1} / 3 · ${esc(s.title)}</div><h2>${esc(s.prompt)}</h2><p class="question-context">${esc(game.stage===0?c.setting+' '+s.context:game.stage===1?'Elige herramientas para comparar los sitios y poner a prueba la hipótesis. Revelarás los datos al ejecutar la medición.':s.context)}</p>${c.id==='circular'&&game.stage===0?'<div class="data-comparison"><div><b>DÍA A</b>1.000 unidades · 10 m³</div><div><b>DÍA B</b>500 unidades · 7 m³</div></div>':''}${isBudget?budgetControls():`<div class="options" role="group" aria-label="Opciones de respuesta">${s.options.map((o,i)=>`<button class="answer-option ${game.selected===i?'selected':''} ${game.revealed&&i===s.correct?'correct':''} ${game.revealed&&game.selected===i&&i!==s.correct?'incorrect':''}" data-answer="${i}" aria-pressed="${game.selected===i}" ${game.revealed?'disabled':''}><span class="letter">${letters[i]}</span><span><span class="option-title">${esc(o.title)}</span>${o.text?`<span class="option-desc">${esc(o.text)}</span>`:''}</span></button>`).join('')}</div>${taskHint()}${feedbackMarkup(c)}<div class="game-action"><button class="primary dark" data-action="${game.revealed?'next':'reveal'}" ${!game.revealed&&(game.selected===null||(game.stage===0&&game.seen.length<3)||!readyTask())?'disabled':''}>${game.revealed?(game.stage===2?'Completar misión':'Siguiente nivel'):(game.stage===0&&game.seen.length<3?'Explora las 3 pistas':game.stage===1?'Ejecutar medición':!readyTask()?'Completa el reto del mapa':'Probar decisión')} <span class="button-arrow">→</span></button></div>`}<p class="career-note">En COLMAYOR lo conectas con <b>${esc(c.course)}</b>.</p></section></div>
<div class="game-bottom">${isBudget?`<section class="votes-panel"><h3>Un plan construido entre todos</h3><p>El docente activa las inversiones propuestas por los equipos. Prueben varias combinaciones y comparen los indicadores.</p><div class="score-row"><span>Recursos disponibles</span><b>6 fichas</b></div><div class="score-row"><span>Producción de referencia</span><b>1.000 unidades</b></div></section>`:votePanel()}<aside class="discussion-panel"><div class="eyebrow">PAUSA PARA PENSAR</div><h3>${game.stage===0?'¿Qué pista apoya tu idea?':game.stage===1?'¿Qué dato cambió tu decisión?':esc(c.reflection)}</h3><p>20 segundos para pensar. 30 para conversar. Una voz por equipo. El reloj organiza; no elimina ni resta puntos.</p><p class="tiny">Hasta 2 puntos por decisión inicial. Revisar una idea con evidencia también es aprender.</p></aside></div><p class="scientific-note">Simulación didáctica. Lugares, instalaciones y cifras ficticios. Los datos no representan límites legales ni sustituyen un diagnóstico ambiental.</p>`;
paintTime();if(restore){const target=$(restore);if(target&&!target.disabled)target.focus({preventScroll:true});}}
const investments=[{id:'agua',name:'Reutilizar un enjuague',cost:3,water:3,energy:0,waste:0,note:'Solo en una etapa compatible: validar calidad, inocuidad y separación de circuitos.'},{id:'calor',name:'Recuperar calor del proceso',cost:3,water:0,energy:100,waste:0,note:'Exige diseño, mantenimiento y una demanda de calor compatible.'},{id:'luces',name:'Cambiar iluminación por LED',cost:1,water:0,energy:20,waste:0,note:'Ahorra energía, aunque su efecto sobre el consumo total es menor.'},{id:'perdidas',name:'Evitar pérdidas de materia prima',cost:2,water:0,energy:0,waste:30,note:'Evita 30 kg de residuos en este escenario; no reduce aquí agua ni energía.'}];
function budgetStats(){const chosen=investments.filter(i=>game.investments.includes(i.id));return {cost:chosen.reduce((a,b)=>a+b.cost,0),water:10-chosen.reduce((a,b)=>a+b.water,0),energy:400-chosen.reduce((a,b)=>a+b.energy,0),waste:chosen.reduce((a,b)=>a+b.waste,0)};}
function budgetField(){const b=budgetStats();return `<section class="field-panel"><div class="field-heading"><b>TABLERO DE PRODUCCIÓN</b><span class="sim-pill">${b.cost}/6 fichas invertidas</span></div><div class="field-scene">${scene('circular')}<span class="plant-effect">${game.investments.includes('agua')?'💧 −30% agua':''} ${game.investments.includes('calor')?'♨ −25% energía':''}</span></div><div class="data-chart"><div class="chart-title">Misma producción: 1.000 unidades</div><div class="bar-row"><span>Agua</span><div class="bar-track"><div class="bar-fill" style="width:${b.water*10}%"></div></div><strong>${b.water} m³</strong></div><div class="bar-row"><span>Energía</span><div class="bar-track"><div class="bar-fill" style="width:${b.energy/4}%"></div></div><strong>${b.energy} kWh</strong></div><div class="budget-goals"><span class="${b.water<=8?'met':''}">${b.water<=8?'✓':'○'} Agua ≤ 8 m³</span><span class="${b.energy<=320?'met':''}">${b.energy<=320?'✓':'○'} Energía ≤ 320 kWh</span></div></div><div class="evidence-readout"><div class="eyebrow">TU OBJETIVO</div><p>Reduce al menos 20% del agua y 20% de la energía. Base: 10 m³ y 400 kWh. Tienes 6 fichas.</p>${b.waste?`<p>Además, evitas ${b.waste} kg de residuos. Un beneficio distinto del objetivo de esta misión.</p>`:''}</div></section>`;}
function budgetControls(){const b=budgetStats(),met=b.water<=8&&b.energy<=320;return `<div class="investment-list">${investments.map(i=>`<button class="investment ${game.investments.includes(i.id)?'selected':''}" data-invest="${i.id}" aria-pressed="${game.investments.includes(i.id)}" ${game.revealed?'disabled':''}><span class="investment-check">${game.investments.includes(i.id)?'✓':'+'}</span><span><b>${i.name}</b><small>${i.water?`−${i.water} m³ agua`:i.energy?`−${i.energy} kWh energía`:`−${i.waste} kg residuos`}</small></span><span class="tokens">${i.cost} ${i.cost===1?'ficha':'fichas'}</span></button>`).join('')}</div>${game.investments.length?`<p class="investment-note">${investments.filter(i=>game.investments.includes(i.id)).map(i=>esc(i.note)).join(' ')}</p>`:''}${game.revealed?`<div class="feedback ${met?'':'warm'}" role="status"><b>${met?'✓ ¡Plan viable en la simulación!':'↻ Revisa las metas y ajusta tu inversión'}</b><p>${met?'Lograste 30% menos agua y 25% menos energía con 6 fichas. Ahora toca validar los ahorros en operación.':'La combinación todavía no cumple ambas metas. Puedes cambiar inversiones y volver a probar sin penalización.'}</p></div>`:''}<div class="game-action"><button class="primary dark" data-action="${game.revealed?(met?'next':'retry-budget'):'reveal-budget'}" ${!game.investments.length?'disabled':''}>${game.revealed?(met?'Completar misión':'Ajustar plan'):'Poner el plan a prueba'} →</button></div>`;}
function reveal(){if(game.revealed||game.selected===null)return;const c=current(),s=c.stages[game.stage];if((game.stage===0&&game.seen.length<3)||!readyTask())return;game.revealed=true;stopTimer();game.records[game.stage]={choice:game.selected,score:s.options[game.selected].score,votes:[...game.votes],points:game.votes.map(x=>x===null?null:s.options[x].score)};renderGame();const feedback=$('.feedback');if(feedback){feedback.setAttribute('tabindex','-1');feedback.focus({preventScroll:true});}chime();speak(s.options[game.selected].feedback);}
function next(){if(game.stage===2){complete();return;}game.stage++;game.selected=null;game.revealed=false;game.votes=settings.teams.map(()=>null);game.activeClue=null;if(game.id==='obra')game.rain=true;setTime();renderGame();const heading=$('.question-panel h2');if(heading){heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});}window.scrollTo(0,0);speak(current().stages[game.stage].prompt);}
function complete(){stopTimer();game.completed=true;history[game.id]={completedAt:new Date().toISOString(),records:game.records,reflection:history[game.id]?.reflection||'',teams:[...settings.teams]};save();renderResults();chime();}
function renderResults(){const c=current();const h=history[c.id];$('#main').innerHTML=`<a class="back" href="#inicio">← Todas las misiones</a><section class="results-hero"><div><div class="eyebrow"><span class="live-dot"></span> MISIÓN COMPLETADA</div><h1>Hoy tomaste decisiones.<br><em>Mañana puedes transformar.</em></h1><p>${esc(c.profession)}</p><a href="#programa" class="primary">Así se aprende en COLMAYOR <span class="button-arrow">↗</span></a></div><div class="results-stamp"><svg viewBox="0 0 60 60" aria-hidden="true"><path d="M17 43C3 14 25 7 48 9c0 25-4 38-26 36M16 50l25-30m-14 16-1-12"/></svg><b>MENTE AMBIENTAL</b><span>EXPLORAR · MEDIR · ACTUAR</span></div></section><div class="two-col"><section class="panel"><div class="eyebrow">BITÁCORA DE LA MISIÓN</div><h2>La evidencia deja huella.</h2>${h.teams.map((t,i)=>{const answered=h.records.filter(r=>r?.points?.[i]!==null&&r?.points?.[i]!==undefined);const score=answered.reduce((sum,r)=>sum+r.points[i],0);return `<div class="score-row"><span>${esc(t)}</span><b>${answered.length?`${score} / ${answered.length*2} puntos`:'Sin votos registrados'}</b></div>`;}).join('')}<p class="tiny" style="margin-top:15px">Puntos de los votos iniciales. ${c.id==='circular'?'El reto de inversión final fue colaborativo y no suma puntos por equipo.':''} La rapidez no afecta el resultado.</p><button class="text-btn" data-action="restart">Volver a jugar esta misión ↻</button></section><section class="panel"><div class="eyebrow">UN ÚLTIMO RETO, SIN RESPUESTA ÚNICA</div><h2>${esc(c.reflection)}</h2><label class="tiny" for="reflection">Una idea del salón para llevar al mundo real</label><textarea id="reflection" class="reflection" placeholder="Nuestra próxima medición sería…" maxlength="700">${esc(h.reflection)}</textarea><p class="tiny" style="margin:8px 0 15px">Se guarda solo en este navegador.</p><div class="route-buttons"><button class="secondary" data-action="save-reflection">Guardar idea</button><a class="primary" href="#mision/${cases[(cases.indexOf(c)+1)%cases.length].id}">Otra misión →</a></div></section></div>`;window.scrollTo(0,0);}
function renderProgram(){const icons=['⌕','⚗','⌁','↗'];$('#main').innerHTML=`<div class="page-top"><div class="eyebrow">TU PRÓXIMO GRAN PROYECTO PUEDES SER TÚ</div></div><section class="program-hero"><div><span class="badge light">INSTITUCIÓN UNIVERSITARIA COLEGIO MAYOR DE ANTIOQUIA</span><h1>Ingeniería<br>Ambiental<span style="color:var(--lime)">.</span></h1><p>${esc(P.intro)}</p><a href="${P.officialUrl}" target="_blank" rel="noopener" class="primary">Conoce el programa oficial ↗</a><div class="program-stats">${P.facts.slice(0,3).map(f=>`<div><b>${esc(f.value)}</b><span>${esc(f.label)}</span></div>`).join('')}</div></div><div class="video-card">${scene('bosque',{corridor:1})}<button class="video-play" data-action="video" aria-label="Reproducir video oficial del programa">▶</button><div class="video-title">Una carrera para entender, diseñar y transformar. <span aria-hidden="true">↗</span></div></div></section><p class="scientific-note">SNIES ${P.facts[3].value} · Registro calificado 024734 de 2022. ${esc(P.recognition)} <a class="source-link" href="${P.officialUrl}" target="_blank" rel="noopener">Ficha oficial</a></p>
<section class="program-section"><div class="eyebrow">EL TRABAJO QUE ACABAS DE PROBAR</div><h2>${esc(P.profile.title)}</h2><p class="tiny">${esc(P.profile.intro)}</p><div class="career-grid">${P.profile.roles.map((r,i)=>`<article class="career-item"><span class="career-icon" aria-hidden="true">${icons[i]}</span><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p></article>`).join('')}</div></section>
<section class="program-section"><div class="eyebrow">TU RUTA · PÉNSUM 1323</div><h2>${esc(P.curriculum.title)}</h2><div class="curriculum">${P.curriculum.blocks.map(b=>`<article><span class="level">NIVELES ${esc(b.levels)}</span><h3>${esc(b.title)}</h3><p>${esc(b.text)}</p></article>`).join('')}</div><div class="program-links"><p class="tiny" style="margin:0">Selección orientativa de asignaturas. Consulta el plan completo y sus requisitos.</p><a class="source-link" href="${P.curriculum.url}" target="_blank" rel="noopener">Ver pénsum completo · PDF ↗</a></div></section>
<section class="program-section"><div class="eyebrow">OPORTUNIDADES PARA COMENZAR</div><h2>Tu talento puede encontrar apoyo.</h2><div class="support-grid">${P.support.map(s=>`<article class="support-card"><span class="badge">${esc(s.badge)}</span><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p><details><summary>¿Qué condiciones debo revisar?</summary><p>${esc(s.eligibility)}</p><p>${esc(s.note)}</p></details><a class="source-link" href="${s.url}" target="_blank" rel="noopener">${esc(s.linkLabel)} ↗</a></article>`).join('')}</div></section>
<section class="program-section"><div class="eyebrow">ADMISIONES · PREPARA TU SIGUIENTE PASO</div><h2>De la curiosidad a la inscripción.</h2><div class="admission-box"><div><span class="badge">${esc(P.costs.pin.period)}</span><span class="pin-price">${esc(P.costs.pin.value)}</span><h3>Inscripción / PIN</h3><p>${esc(P.costs.pin.text)}</p><a class="primary dark" href="${P.admissionsUrl}" target="_blank" rel="noopener">Consultar guía de admisiones ↗</a></div><div><h3>Antes de inscribirte</h3><ol><li>Consulta fechas, documentos y condiciones de la convocatoria.</li><li>Revisa la oferta de Robledo o Comuna 1 y las posibles exenciones.</li><li>${esc(P.costs.pin.next)}</li><li>Pregunta por apoyos y confirma los requisitos del periodo.</li></ol><p class="tiny">${esc(P.locations)}</p><details><summary class="text-btn">Consultar referencia de matrícula 2026</summary><p class="tiny">${esc(P.costs.tuition.period)} · Valores en COP, sin aplicar apoyos.</p><table class="tuition-table"><caption class="tiny" style="text-align:left;margin-bottom:9px">Referencia histórica de matrícula</caption><tbody>${P.costs.tuition.rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(r.value)}</td></tr>`).join('')}</tbody></table><p class="tiny">${esc(P.costs.tuition.note)}</p><p class="tiny">${esc(P.costs.tuition.futureNote)}</p><a class="source-link" href="${P.costs.tuition.url}" target="_blank" rel="noopener">Tarifas oficiales ↗</a></details></div></div></section><section class="program-contact"><div><h3>Las buenas preguntas abren caminos.</h3><p>Conversa con el programa sobre tu futuro en Ingeniería Ambiental.</p></div><a class="primary dark" href="mailto:${P.contact}">${P.contact} ↗</a></section><p class="scientific-note">${P.checkedAtLabel}. Valores y beneficios sujetos a vigencia y verificación institucional. <button class="text-btn" data-action="sources">Consultar fuentes</button></p>`;}
function renderTeacher(){const count=settings.teams.length;$('#main').innerHTML=`<section class="page-top"><div class="eyebrow">UN PROYECTOR. MUCHAS IDEAS.</div><h1>Hoy el salón es<br>un equipo de ingeniería.</h1><p>Facilita una aventura de 25 minutos. Tú controlas la pantalla y registras las decisiones; los estudiantes exploran, discuten y proponen.</p></section><div class="teacher-layout"><section class="panel"><h2>Prepara la partida</h2><p>La sesión se conserva en este navegador. Usa nombres de equipo, sin datos personales.</p><label class="setting-field" for="team-count">Equipos en el salón<span>Pueden votar con las manos o mostrar tarjetas A, B y C.</span><select id="team-count">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${n===count?'selected':''}>${n===1?'Un solo grupo':n+' equipos'}</option>`).join('')}</select></label><div id="team-inputs">${settings.teams.map((t,i)=>`<label class="setting-field" for="team-${i}">Equipo ${i+1}<input id="team-${i}" class="team-name-input" maxlength="26" value="${esc(t)}"></label>`).join('')}</div><label class="setting-field" for="round-time">Tiempo sugerido por ronda<span>Sin penalizaciones. Puedes pausar o reiniciar cuando quieras.</span><select id="round-time">${[30,45,60,90].map(n=>`<option value="${n}" ${settings.seconds===n?'selected':''}>${n} segundos</option>`).join('')}</select></label><button class="primary dark wide-button" data-action="save-settings">Guardar y comenzar →</button><p class="session-status">Guardado local · no se envían respuestas a un servidor.</p></section><section class="panel"><h2>Una guía para enamorar, jugando</h2><div class="teacher-guide">${[['Abre con una pregunta · 2 min','¿Qué creen que hace un ingeniero ambiental? Escucha ideas y asigna roles: observar, analizar y ser vocero.'],['Entren al territorio · 4–5 min por misión','Toquen las pistas. Antes de medir, propongan una hipótesis. Cada equipo elige A, B o C y explica su razón.'],['Revelen y vuelvan a pensar','Registra los votos antes de revelar. Un error abre la conversación. Pueden revisar el voto; se conserva el puntaje inicial.'],['Prueben soluciones, vean consecuencias','Muevan el control de tratamiento, tracen conexiones, instalen defensas y distribuyan fichas de inversión. Comparen alternativas.'],['Conecten con su futuro · 3 min','Pregunten qué medirían mañana y qué reto les gustó más. Cierren con el programa, el pénsum y las oportunidades de apoyo.']].map(([h,p],i)=>`<div class="guide-step"><span>${i+1}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div><div class="brief-media"><button data-action="teacher-audio" aria-label="Escuchar guía de inicio">▶</button><span>Guía de inicio con lectura opcional. Todo el contenido también está escrito.</span></div><p class="scientific-note">Aprendizaje basado en problemas, predicción antes de evidencia, retroalimentación inmediata, colaboración y reflexión. Las misiones son independientes y no eliminan participantes.</p></section></div><section class="panel scoreboard"><div class="section-head"><div><div class="eyebrow">BITÁCORA DEL SALÓN</div><h2>El recorrido que van construyendo.</h2></div><button class="text-btn" data-action="export">Descargar bitácora ↓</button></div>${cases.map(c=>`<div class="score-row"><span>${esc(c.title)}</span><b>${history[c.id]?'✓ Exploración completada':'Por explorar'}</b></div>`).join('')}<div class="route-buttons" style="margin-top:20px"><a href="#inicio" class="primary">Elegir misión →</a><button class="secondary" data-action="reset-dialog">Nueva sesión</button></div><p class="tiny" style="margin:15px 0 0">La bitácora no se sincroniza entre dispositivos. Para cada nueva clase, inicia una sesión.</p></section>`;}
const toolsList=[{name:'Oxímetro + termómetro',what:'Miden oxígeno disuelto y temperatura en campo. Un pez buscando aire es una pista; el equipo ayuda a comprobarla.',use:'Calibra el sensor. Compara sitios y horas, registra temperatura y condiciones. La DBO₅ se analiza por separado en laboratorio, durante cinco días.',path:'<path d="M40 25h45v72H40zM48 34h29v25H48zM52 70h6m9 0h6M52 80h6m9 0h6M85 60h9q15 0 15 15v21M103 96h12v17h-12Z"/><path d="m52 49 5-6 5 7 8-11"/>'},{name:'Turbidímetro + muestreo',what:'La turbidez indica cuánto dispersan la luz las partículas del agua. El laboratorio mide sólidos suspendidos.',use:'Compara aguas arriba y abajo antes y después de la lluvia. NTU y mg/L son mediciones diferentes; no las intercambies sin una relación validada.',path:'<path d="M24 48h73v60H24zM35 61h28v20H35zM42 96h37M45 48V18h31v30M49 29h23M83 61v18M91 61v18"/><path d="M50 37q10-7 20 0"/>'},{name:'SIG + cámaras trampa',what:'Un sistema de información geográfica conecta mapas y datos. Las cámaras registran fauna sin estar siempre presentes.',use:'Ubica parches, coberturas y barreras. Compara igual esfuerzo de muestreo y varias temporadas. Menos registros no prueban por sí solos que una especie desapareció.',path:'<path d="m14 31 31-10 31 10 31-10v72l-31 10-31-10-31 10Zm31-10v72m31-62v72"/><path d="M57 44h36v25H57zM64 44l4-6h12l4 6"/><circle cx="75" cy="56" r="7"/>'},{name:'Caudalímetro + registro',what:'Medir cuánto fluye permite estimar consumo y carga contaminante. El volumen importa tanto como la concentración.',use:'En el caso de agua: carga (kg/d) = concentración (mg/L) × caudal (L/s) × 0,0864. Diluir reduce concentración, pero no elimina la masa.',path:'<path d="M10 69h30V51h45v18h30v20H85v18H40V89H10"/><circle cx="63" cy="48" r="24" fill="#e8efde"/><path d="m63 48 12-13M49 43h3m23 0h3m-15-14v4"/>'},{name:'Medidor de energía',what:'Registra energía consumida. Junto con la producción permite comparar procesos y probar mejoras.',use:'Compara kWh por unidad con la misma calidad y alcance de medición. Una factura menor puede deberse a menor producción, sin que haya más eficiencia.',path:'<path d="M32 15h62v96H32zM41 27h44v28H41zM44 40h9m8 0h9m8 0h3"/><path d="m67 65-17 22h13l-4 17 17-23H64Z"/>'},{name:'Balanza + balance de materiales',what:'Pesar entradas, producto y residuos hace visibles las pérdidas. Es el primer paso para prevenirlas.',use:'Define un periodo y pesa con criterios comparables. Revisa si una solución evita residuos o solo los traslada a otra corriente, etapa o lugar.',path:'<path d="M18 90h90v20H18zM63 90V25m-37 8 74-14M26 33 10 68h32L26 33Zm74-14L84 54h32L100 19Z"/><circle cx="63" cy="23" r="5"/>'}];
function renderTools(){$('#main').innerHTML=`<section class="page-top"><div class="eyebrow">HAZ VISIBLE LO INVISIBLE</div><h1>La curiosidad es el inicio.<br>Los datos son tu superpoder.</h1><p>Estas son algunas herramientas de un ingeniero ambiental. Cada una responde una pregunta distinta.</p></section><div class="tool-grid">${toolsList.map(t=>`<article class="tool-card"><div class="tool-illustration"><svg viewBox="0 0 125 125" aria-hidden="true">${t.path}</svg></div><div class="tool-body"><h2>${t.name}</h2><p>${t.what}</p><details><summary>¿Cómo se usa con criterio?</summary><p>${t.use}</p></details></div></article>`).join('')}</div><div class="invitation"><div><h3>Un instrumento no decide por ti.</h3><p>Diseñar dónde medir, interpretar la incertidumbre y escuchar a las personas también es ingeniería.</p></div><a class="text-btn" href="#inicio">Poner el kit a prueba ↗</a></div>`;}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
function sources(){modal(`<h2>Una experiencia con fundamento.</h2><div class="source-list"><p>${P.checkedAtLabel}. Las cifras de admisión se muestran con su periodo. Consulta la nueva convocatoria antes de tomar una decisión.</p>${P.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><small>${esc(s.scope)}</small>`).join('')}<h3>Sobre las misiones</h3><p>Escenarios y datos sintéticos con fines educativos. No representan empresas, ecosistemas o proyectos reales ni límites legales. Los resultados de los simuladores son simplificaciones declaradas, no pronósticos ambientales.</p><h3>Diseño y multimedia</h3><p>Diseño educativo para el COLMAYOR. Este aplicativo es un recurso de orientación y no reemplaza sus canales oficiales. Paisaje de portada generado con IA; mapas e instrumentos son ilustraciones originales. Video enlazado desde la ficha institucional, alojado en YouTube. Lectura opcional con la voz disponible en tu navegador. Tipografías locales Manrope y DM Sans (OFL); símbolos DejaVu, con licencias incluidas.</p><p>Interacciones: retos basados en problemas, exploración, decisiones con evidencia, colaboración, retroalimentación y reflexión. No se recopilan nombres de estudiantes.</p></div>`);}
function exportLog(){const lines=['BITÁCORA · MISIÓN AMBIENTAL COLMAYOR',`Exportada: ${new Date().toLocaleString('es-CO')}`,'Datos y escenarios didácticos. Votos guardados solo en este navegador.',''];for(const c of cases){const h=history[c.id];lines.push(c.title);if(!h){lines.push('Por explorar','');continue;}h.teams.forEach((t,i)=>{let records=h.records.filter(r=>r?.points?.[i]!=null);lines.push(`${t}: ${records.length?records.reduce((a,r)=>a+r.points[i],0)+' / '+records.length*2:'sin votos registrados'}`);});lines.push('Idea del salón: '+(h.reflection||'Sin registrar'),'');}const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bitacora-mision-ambiental.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Bitácora descargada.');}
function saveSettings(){const count=Number($('#team-count').value);settings.teams=Array.from({length:count},(_,i)=>$(`#team-${i}`)?.value.trim().slice(0,26)||`Equipo ${i+1}`);settings.seconds=Number($('#round-time').value);game=null;save();location.hash='inicio';toast('Partida preparada. Elige tu misión.');}
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-route]');if(!el)return;if(el.dataset.route){location.hash=el.dataset.route;return;}if(el.id==='close-modal'){ $('#modal').close();if('speechSynthesis' in window)speechSynthesis.cancel();return;}if(el.id==='sound-toggle'){if(!('speechSynthesis' in window)){toast('La lectura en voz alta no está disponible en este navegador.');return;}narrate=!narrate;el.setAttribute('aria-pressed',narrate);el.setAttribute('aria-label',narrate?'Desactivar lectura en voz alta':'Activar lectura en voz alta');if(!narrate)speechSynthesis.cancel();else speak(game&&route.startsWith('mision/')?current().stages[game.stage].prompt:'Lectura activada. Explora, mide y transforma.');return;}if(el.id==='timer-toggle'){toggleTimer();return;}if(el.id==='timer-reset'){setTime();return;}if(el.id==='fullscreen'){document.body.classList.toggle('fullscreen-mode');el.setAttribute('aria-label',document.body.classList.contains('fullscreen-mode')?'Salir de vista para proyector':'Activar vista para proyector');return;}
if(el.dataset.clue!==undefined&&game){const i=Number(el.dataset.clue);if(!game.seen.includes(i)){game.seen.push(i);chime();}game.activeClue=i;renderGame();speak(current().hotspots[i].text);return;}
if(el.dataset.answer!==undefined&&game&&!game.revealed){game.selected=Number(el.dataset.answer);renderGame();return;}
if(el.dataset.vote!==undefined&&game){const i=Number(el.dataset.vote);game.votes[i]=Number(el.dataset.value);if(game.revealed){toast('Voto revisado. El puntaje inicial se conserva.');}renderGame();return;}
if(el.dataset.corridor!==undefined&&game){game.corridor=Number(el.dataset.corridor);renderGame();return;}
if(el.dataset.weather!==undefined&&game){game.rain=el.dataset.weather==='true';renderGame();return;}
if(el.dataset.control!==undefined&&game){const i=Number(el.dataset.control);game.controls=game.controls.includes(i)?game.controls.filter(n=>n!==i):[...game.controls,i];renderGame();return;}
if(el.dataset.invest&&game&&!game.revealed){const id=el.dataset.invest;const item=investments.find(x=>x.id===id);if(game.investments.includes(id))game.investments=game.investments.filter(x=>x!==id);else if(budgetStats().cost+item.cost<=6)game.investments.push(id);else {toast('Solo tienes 6 fichas. Retira otra inversión para liberar recursos.');return;}renderGame();return;}
const action=el.dataset.action;if(action==='sources')sources();else if(action==='reveal')reveal();else if(action==='next')next();else if(action==='reveal-budget'){game.revealed=true;const b=budgetStats();if(b.water<=8&&b.energy<=320){game.records[2]={choice:0,score:2,votes:[],points:[],investments:[...game.investments]};chime();}renderGame();}else if(action==='retry-budget'){game.revealed=false;renderGame();}else if(action==='restart'){startGame(game.id);window.scrollTo(0,0);}else if(action==='save-reflection'){history[game.id].reflection=$('#reflection').value.trim();save();toast('Idea guardada en la bitácora del salón.');}else if(action==='save-settings')saveSettings();else if(action==='export')exportLog();else if(action==='reset-dialog')modal('<h2>Empezar una nueva clase</h2><p>Se borrarán los resultados y las ideas de este navegador. Puedes descargar la bitácora antes de continuar.</p><div class="route-buttons"><button class="secondary" data-action="export">Descargar bitácora</button><button class="primary dark" data-action="reset-confirm">Iniciar nueva sesión</button></div>');else if(action==='reset-confirm'){history={};game=null;save();$('#modal').close();renderTeacher();toast('Nueva sesión lista.');}else if(action==='video')modal(`<h2>${P.video.title}</h2><p class="tiny">${P.video.description} La reproducción carga contenido desde YouTube.</p><iframe class="modal-video" src="${P.video.embedUrl}?rel=0" title="Video oficial Ingeniería Ambiental COLMAYOR" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture; fullscreen" allowfullscreen></iframe><p><a href="${P.video.url}" class="source-link" target="_blank" rel="noopener">Abrir en YouTube · subtítulos si están disponibles ↗</a></p><p class="tiny">El perfil y el pénsum también están disponibles en texto en esta página.</p>`);else if(action==='teacher-audio'){if(!('speechSynthesis' in window)){toast('La lectura no está disponible en este navegador.');return;}const before=narrate;narrate=true;speak('Bienvenidos a Misión Ambiental. Formen equipos. Una persona observa, otra analiza y otra comunica. Primero exploramos las pistas, luego elegimos qué medir y finalmente probamos una solución. Equivocarse nos ayuda a hacer mejores preguntas.');narrate=before;}});
document.addEventListener('input',e=>{if(e.target.id==='treatment'&&game){game.sim=Number(e.target.value);$('#treatment-percent').textContent=`${game.sim}% remoción`;$('#dbo-value').textContent=`${Math.round(420*(1-game.sim/100))} mg/L`;$('#load-value').textContent=`${(108.864*(1-game.sim/100)).toFixed(1)} kg/d`;$('#scene').innerHTML=scene('agua',{stage:2,sim:game.sim});const hint=$('.task-hint');if(hint){hint.classList.toggle('mission-task-complete',readyTask());hint.textContent=(readyTask()?'✓ ':'↳ ')+'Reto: ajusta el tratamiento para reducir al menos 80% de la carga del vertimiento. Meta didáctica, no límite legal.';}const action=$('[data-action="reveal"]');if(action){action.disabled=game.selected===null||!readyTask();action.innerHTML=(readyTask()?'Probar decisión':'Completa el reto del mapa')+' <span class="button-arrow">→</span>';}}});
document.addEventListener('change',e=>{if(e.target.id==='team-count'){const n=Number(e.target.value);const previous=Array.from(document.querySelectorAll('.team-name-input')).map(x=>x.value);$('#team-inputs').innerHTML=Array.from({length:n},(_,i)=>`<label class="setting-field" for="team-${i}">Equipo ${i+1}<input id="team-${i}" class="team-name-input" maxlength="26" value="${esc(previous[i]||`Equipo ${i+1}`)}"></label>`).join('');}});
$('#modal').addEventListener('close',()=>{$('#modal-content').innerHTML='';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('fullscreen-mode');}if(e.key===' '&&e.target===document.body&&game&&route.startsWith('mision/')){e.preventDefault();toggleTimer();}});
window.addEventListener('hashchange',navigate);navigate();
})();
